        return;
    }
    HashMap<UUID, CompanionListPacket.Entry> byUuid = new HashMap<UUID, CompanionListPacket.Entry>();
    for (CompanionListPacket.Entry entry : entries) {
        byUuid.put(entry.uuid(), entry);
    }
    for (Transaction transaction : new ArrayList<Transaction>(ACTIVE.values())) {
