                }
                yield false;
            }
            case CompanionAction.RECALL -> {
                if (entry != null && !entry.deployed() && !entry.ridden()) {
                    yield true;
                }
                yield false;
            }
            default -> false;
        }))) continue;
        CompanionWheelTransactionService.finish(player, transaction, WheelIntentPhase.COMPLETED, "authoritative_roster");
    }
}

