import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;

final class TerminalResultCache<K, T> {
    private final Map<K, Entry<T>> entries = new HashMap<K, Entry<T>>();

    TerminalResultCache() {
    }

    T get(K key) {
        Entry<T> entry = key == null ? null : this.entries.get(key);
        return entry == null ? null : (T)entry.value();
    }

    boolean contains(K key) {
        return key != null && this.entries.containsKey(key);
    }

    void put(K key, T value, long expiresAt) {
        if (key != null && value != null) {
            this.entries.put(key, new Entry<T>(value, expiresAt));
        }
    }

    int expire(long now) {
        int removed = 0;
        Iterator<Entry<T>> iterator = this.entries.values().iterator();
        while (iterator.hasNext()) {
            if (now < iterator.next().expiresAt()) continue;
            iterator.remove();
            ++removed;
        }
        return removed;
    }

    void clear() {
        this.entries.clear();
    }

    private record Entry<T>(T value, long expiresAt) {
    }
}

