public final class CompanionOperationLockService {
    private static final int DEFAULT_TIMEOUT_TICKS = 600;
    private static final Map<UUID, ActiveOperation> ACTIVE = new HashMap<UUID, ActiveOperation>();
    private static final Map<UUID, CompanionControlCoordinator.Lease> CONTROL = new HashMap<UUID, CompanionControlCoordinator.Lease>();

    private CompanionOperationLockService() {
    }

    public static boolean tryBegin(ServerPlayer player, UUID companionId, Operation operation, String source, int timeoutTicks) {
        if (player == null || companionId == null || operation == null) {
            return false;
        }
        long now = player.m_284548_().m_46467_();
        BeginResult result = CompanionOperationLockService.begin(player.m_20148_(), companionId, operation, source, now, timeoutTicks);
        if (!result.accepted()) {
            ActiveOperation current = result.previous();
            FindMeDebugLogger.lifecycle("OPERATION_REJECTED", player, companionId, null, current.operation.name(), operation.name(), "locked_by_" + current.source, false, false);
            return false;
        }
        if (result.previous() != null) {
            ActiveOperation current = result.previous();
            FindMeDebugLogger.lifecycle("OPERATION_LOCK_EXPIRED", player, companionId, null, current.operation.name(), operation.name(), current.source, false, false);
        }
        FindMeDebugLogger.lifecycle("OPERATION_STARTED", player, companionId, null, "-", operation.name(), source, false, false);
        return true;
    }

    static BeginResult begin(UUID playerUuid, UUID companionId, Operation operation, String source, long now, int timeoutTicks) {
        int priority;
        CompanionControlCoordinator.Lease lease;
        ActiveOperation current = ACTIVE.get(companionId);
        if (current != null && current.expiresAt >= now) {
            return new BeginResult(false, current);
        }
        CompanionControlCoordinator.Lease previousLease = CONTROL.remove(companionId);
        if (previousLease != null) {
            previousLease.close();
        }
        if ((lease = (CompanionControlCoordinator.Lease)CompanionControlCoordinator.acquire(companionId, playerUuid, source, priority = operation == Operation.EXTERNAL ? 300 : 600, now, timeoutTicks, CompanionOperationLockService.domains(operation)).orElse(null)) == null) {
            return new BeginResult(false, current);
        }
        ACTIVE.put(companionId, new ActiveOperation(playerUuid, operation, source, now, now + (long)Math.max(1, timeoutTicks)));
        CONTROL.put(companionId, lease);
        return new BeginResult(true, current);
    }

    public static boolean tryBeginExternal(UUID playerUuid, UUID companionId, String source, long now, int timeoutTicks) {
        if (playerUuid == null || companionId == null || source == null || source.isBlank()) {
            return false;
        }
        return CompanionOperationLockService.begin(playerUuid, companionId, Operation.EXTERNAL, source, now, timeoutTicks).accepted();
    }

    public static boolean tryBegin(ServerPlayer player, UUID companionId, Operation operation, String source) {
        return CompanionOperationLockService.tryBegin(player, companionId, operation, source, 600);
    }

    public static void end(ServerPlayer player, UUID companionId, Operation operation, String reason) {
        if (companionId == null) {
            return;
        }
        ActiveOperation current = ACTIVE.get(companionId);
        if (current == null || current.operation != operation) {
            return;
        }
        ACTIVE.remove(companionId);
        CompanionOperationLockService.closeControl(companionId);
        FindMeDebugLogger.lifecycle("OPERATION_FINISHED", player, companionId, null, operation.name(), "-", reason, false, false);
    }

    public static boolean endIfSource(UUID companionId, Operation operation, String source) {
        ActiveOperation current = CompanionOperationLockService.get(companionId);
        if (current == null || current.operation != operation || !current.source.equals(source)) {
            return false;
        }
        ACTIVE.remove(companionId);
        CompanionOperationLockService.closeControl(companionId);
        return true;
    }

