package com.kuzhi.findme.server.data;

import com.kuzhi.findme.server.api.CompanionLifecycleEventService;
import com.kuzhi.findme.server.core.FindMePerformanceMonitor;
import com.kuzhi.findme.server.data.CompanionRuntimeIndex;
import com.kuzhi.findme.server.data.FindMeWorldMigrationService;
import com.kuzhi.findme.server.data.FindMeWorldSavedData;
import com.kuzhi.findme.server.data.HomeResidentIndex;
import com.kuzhi.findme.server.data.PlayerCompanionData;
import com.kuzhi.findme.server.data.PlayerCompanionDataCodec;
import com.kuzhi.findme.server.data.RevisionedPlayerDataCache;
import com.kuzhi.findme.server.ui.CompanionSpellItemReturnService;
import com.kuzhi.findme.server.ui.FindMeDefaultSettingsService;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.WeakHashMap;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;

public final class CompanionDataService {
    private static final Map<MinecraftServer, RevisionedPlayerDataCache> DATA_CACHES = new WeakHashMap<MinecraftServer, RevisionedPlayerDataCache>();

    private CompanionDataService() {
    }

    public static PlayerCompanionData data(ServerPlayer player) {
        FindMeWorldSavedData world = FindMeWorldMigrationService.ensureMigrated(player);
        long revision = world.playerRevision(player.m_20148_());
        PlayerCompanionData cached = CompanionDataService.cached(player.m_20194_(), player.m_20148_(), revision);
        if (cached != null) {
            return cached;
        }
        long startedAt = FindMePerformanceMonitor.start();
        boolean hasRoot = world.hasPlayerRoot(player.m_20148_());
        PlayerCompanionData data = world.decodePlayerData(player.m_20148_());
        if (!hasRoot) {
            data.setUiSettings(FindMeDefaultSettingsService.loadUiDefaults());
        }
        FindMePerformanceMonitor.recordDataDecode(startedAt);
        CompanionDataService.cache(player.m_20194_(), player.m_20148_(), revision, data);
        return data;
    }

    public static long revision(ServerPlayer player) {
        return player == null ? 0L : FindMeWorldMigrationService.ensureMigrated(player).playerRevision(player.m_20148_());
    }

    public static HomeResidentIndex homeResidentIndex(ServerPlayer player) {
        return player == null ? HomeResidentIndex.empty() : FindMeWorldMigrationService.ensureMigrated(player).homeResidentIndex(player.m_20148_());
    }

    public static CompanionRuntimeIndex runtimeIndex(ServerPlayer player) {
        return player == null ? CompanionRuntimeIndex.empty() : FindMeWorldMigrationService.ensureMigrated(player).companionRuntimeIndex(player.m_20148_());
    }

    public static long revision(MinecraftServer server, UUID playerUuid) {
        return server == null || playerUuid == null ? 0L : FindMeWorldSavedData.get(server).playerRevision(playerUuid);
    }

    public static void save(ServerPlayer player, PlayerCompanionData data) {
        long startedAt = FindMePerformanceMonitor.start();
        FindMeWorldSavedData world = FindMeWorldMigrationService.ensureMigrated(player);
        Set<UUID> changed = data.lifecycleChanges();
        long beforeRevision = world.playerRevision(player.m_20148_());
        PlayerCompanionData before = changed.isEmpty() ? null : world.decodePlayerData(player.m_20148_());
        CompanionSpellItemReturnService.deliverPending(player, data);
        CompoundTag container = new CompoundTag();
        data.save(container);
        long afterRevision = world.putPlayerRoot(player.m_20148_(), PlayerCompanionDataCodec.rootForImmediateStore(container));
        data.clearLifecycleChanges();
        CompanionDataService.cache(player.m_20194_(), player.m_20148_(), afterRevision, data);
        if (!changed.isEmpty()) {
            CompanionLifecycleEventService.publishChanges(player.m_20194_(), player.m_20148_(), before, data, changed, beforeRevision, afterRevision);
        }
        FindMePerformanceMonitor.recordDataSave(startedAt);
    }

    public static PlayerCompanionData data(MinecraftServer server, UUID playerUuid) {
        if (server == null || playerUuid == null) {
